inline LDMT::LDMT(const LDMT &o)
      : SITE((o.SITE) ? new SITT(*o.SITE) : nullptr),
        AZIMUTH(o.AZIMUTH),
        REFERENCES(o.REFERENCES),
        AGENCY_NAME(o.AGENCY_NAME),
        NET(o.NET),
        ROCKET_CONFIGURATION((o.ROCKET_CONFIGURATION) ? new ROCT(*o.ROCKET_CONFIGURATION) : nullptr),
        MISSION_NAME(o.MISSION_NAME),
        MISSION_DESCRIPTION(o.MISSION_DESCRIPTION),
        MISSION_TYPE(o.MISSION_TYPE),
        ORBIT_TYPE(o.ORBIT_TYPE),
        WEATHER_CONDITIONS(o.WEATHER_CONDITIONS),
        LAUNCH_STATUS(o.LAUNCH_STATUS),
        WEBCAST_URL(o.WEBCAST_URL),
        MEDIA_LINKS(o.MEDIA_LINKS),
        EARLIEST_LAUNCH_TIMES(o.EARLIEST_LAUNCH_TIMES),
        LATEST_LAUNCH_TIMES(o.LATEST_LAUNCH_TIMES),
        LCOLA_WINDOW_CLOSURES(o.LCOLA_WINDOW_CLOSURES),
        TRACKING_REQUIREMENTS(o.TRACKING_REQUIREMENTS),
        COLA_SCREEN_DURATION(o.COLA_SCREEN_DURATION),
        PROBABILITY_OF_COLLISION_THRESHOLD(o.PROBABILITY_OF_COLLISION_THRESHOLD),
        COLA_RUNS_REQUIRED(o.COLA_RUNS_REQUIRED),
        ORBITAL_PARAMETERS(o.ORBITAL_PARAMETERS) {
  POINTS_OF_CONTACT.reserve(o.POINTS_OF_CONTACT.size());
  for (const auto &POINTS_OF_CONTACT_ : o.POINTS_OF_CONTACT) { POINTS_OF_CONTACT.emplace_back((POINTS_OF_CONTACT_) ? new EPMT(*POINTS_OF_CONTACT_) : nullptr); }
  OPERATIONS_POINTS_OF_CONTACT.reserve(o.OPERATIONS_POINTS_OF_CONTACT.size());
  for (const auto &OPERATIONS_POINTS_OF_CONTACT_ : o.OPERATIONS_POINTS_OF_CONTACT) { OPERATIONS_POINTS_OF_CONTACT.emplace_back((OPERATIONS_POINTS_OF_CONTACT_) ? new EPMT(*OPERATIONS_POINTS_OF_CONTACT_) : nullptr); }
  OBJECTS.reserve(o.OBJECTS.size());
  for (const auto &OBJECTS_ : o.OBJECTS) { OBJECTS.emplace_back((OBJECTS_) ? new CATT(*OBJECTS_) : nullptr); }
  COLA_POINTS_OF_CONTACT.reserve(o.COLA_POINTS_OF_CONTACT.size());
  for (const auto &COLA_POINTS_OF_CONTACT_ : o.COLA_POINTS_OF_CONTACT) { COLA_POINTS_OF_CONTACT.emplace_back((COLA_POINTS_OF_CONTACT_) ? new EPMT(*COLA_POINTS_OF_CONTACT_) : nullptr); }
  BURN_OUT_VECTORS.reserve(o.BURN_OUT_VECTORS.size());
  for (const auto &BURN_OUT_VECTORS_ : o.BURN_OUT_VECTORS) { BURN_OUT_VECTORS.emplace_back((BURN_OUT_VECTORS_) ? new BOVT(*BURN_OUT_VECTORS_) : nullptr); }
}

